def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if instance is None:
        return ''
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields if version == '1.0' else instance.gpx_10_fields + instance.gpx_11_fields
    attributes = ''
    body = ''
    skip_until = None
    for field in fields:
        if isinstance(field, str):
            sentinel, fieldname = _check_dependents(instance, field)
            if sentinel:
                skip_until = fieldname
            else:
                if skip_until and field == skip_until:
                    skip_until = None
                elif skip_until and field.lstrip('/') == skip_until:
                    skip_until = None
            continue
        if skip_until:
            continue
        if field.attribute:
            xml_value = field.to_xml(getattr(instance, field.name), version, nsmap, prettyprint=prettyprint, indent=indent + '  ')
            if xml_value:
                attributes += ' ' + xml_value
        else:
            value = getattr(instance, field.name)
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent + '  ')
            if xml_value:
                body += xml_value
    for attr_name, attr_value in custom_attributes.items():
        attributes += f' {attr_name}="{attr_value}"'
    if not body and not empty_body:
        return ''
    if prettyprint:
        result = f'\n{indent}<{tag}{attributes}>{body}\n{indent}</{tag}>'
    else:
        result = f'<{tag}{attributes}>{body}</{tag}>'
    return result
```

